selector_to_html = {"a[href=\"dispatch-through-yaml-file.html#config-fields\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Config Fields<a class=\"headerlink\" href=\"#config-fields\" title=\"Link to this heading\">#</a></h2>", "a[href=\"debugg-and-diagonostics.html#troubleshoot-numerical-precision-issues-through-precision-bisection\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Troubleshoot numerical precision issues through Precision Bisection<a class=\"headerlink\" href=\"#troubleshoot-numerical-precision-issues-through-precision-bisection\" title=\"Link to this heading\">#</a></h2><p>When numerical differences appear, isolate the responsible layer. If output diverges at Step N but not Step N-1, the responsible layer/op is isolated.</p>", "a[href=\"dispatch-through-yaml-file.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch through YAML config file<a class=\"headerlink\" href=\"#dispatch-through-yaml-config-file\" title=\"Link to this heading\">#</a></h1><p>The plugin ships with a sample config file <code class=\"docutils literal notranslate\"><span class=\"pre\">config/sample.yaml</span></code> with all available options. Copy it and customize:</p>", "a[href=\"debugg-and-diagonostics.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Debugging and diagnostics<a class=\"headerlink\" href=\"#debugging-and-diagnostics\" title=\"Link to this heading\">#</a></h1><p>This section introduces diagnostics on ops dispatch.</p>", "a[href=\"vendor-integration.html#operator-implementations-impl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Operator implementations (impl/)<a class=\"headerlink\" href=\"#operator-implementations-impl\" title=\"Link to this heading\">#</a></h2><p>Each op function receives standardized arguments (same as vllm-plugin-FL):</p>", "a[href=\"dispatch-through-yaml-file.html#common-recipes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Common Recipes<a class=\"headerlink\" href=\"#common-recipes\" title=\"Link to this heading\">#</a></h2><p>Each recipe shows a YAML config and expected dispatch result. Use <a class=\"reference internal\" href=\"debugg-and-diagonostics.html\"><span class=\"std std-doc\">Dispatch Log</span></a> to verify.</p>", "a[href=\"dispatch-through-environment-variables.html#layer-1-aten-replacement-flaggems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Layer 1 \u2014 ATen Replacement (FlagGems)<a class=\"headerlink\" href=\"#layer-1-aten-replacement-flaggems\" title=\"Link to this heading\">#</a></h2>", "a[href=\"dispatch-through-environment-variables.html#layer-3-distributed-communication\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Layer 3 \u2014 Distributed Communication<a class=\"headerlink\" href=\"#layer-3-distributed-communication\" title=\"Link to this heading\">#</a></h2>", "a[href=\"vendor-integration.html#vendors-backend-auto-discovery\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Vendor\u2019s backend auto-discovery<a class=\"headerlink\" href=\"#vendors-backend-auto-discovery\" title=\"Link to this heading\">#</a></h2><p>The plugin scans <code class=\"docutils literal notranslate\"><span class=\"pre\">dispatch/backends/vendor/*/register_ops.py</span></code> at startup. If is_available() returns True, the vendor\u2019s ops are registered. No other files need modification.</p>", "a[href=\"#operator-dispatch-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator Dispatch User Guide<a class=\"headerlink\" href=\"#operator-dispatch-user-guide\" title=\"Link to this heading\">#</a></h1><p>The dispatch system provides three layers of operator replacement. You can control each layer independently and flexibly.</p><p>The dispatch system supports both YAML configuration and environment variables for fine-grained control. Environment variables take precedence over YAML config.</p>", "a[href=\"dispatch-through-environment-variables.html#layer-2-fused-op-dispatch\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Layer 2 \u2014 Fused Op Dispatch<a class=\"headerlink\" href=\"#layer-2-fused-op-dispatch\" title=\"Link to this heading\">#</a></h2>", "a[href=\"dispatch-through-environment-variables.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch through environment variables<a class=\"headerlink\" href=\"#dispatch-through-environment-variables\" title=\"Link to this heading\">#</a></h1><p>All plugin behavior is controlled by environment variables with the  <code class=\"docutils literal notranslate\"><span class=\"pre\">SGLANG_FL_*</span></code> prefix.</p>", "a[href=\"dispatch-through-environment-variables.html#examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h2>", "a[href=\"dispatch-through-environment-variables.html#system-debug\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">System / Debug<a class=\"headerlink\" href=\"#system-debug\" title=\"Link to this heading\">#</a></h2>", "a[href=\"debugg-and-diagonostics.html#aten-replacement-log\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">ATen replacement log<a class=\"headerlink\" href=\"#aten-replacement-log\" title=\"Link to this heading\">#</a></h2><p>Record which PyTorch ATen ops were replaced by FlagGems:</p>", "a[href=\"debugg-and-diagonostics.html#common-issues\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Common Issues<a class=\"headerlink\" href=\"#common-issues\" title=\"Link to this heading\">#</a></h2>", "a[href=\"vendor-integration.html#backend-class-my-chip-py\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Backend class (my_chip.py)<a class=\"headerlink\" href=\"#backend-class-my-chip-py\" title=\"Link to this heading\">#</a></h2>", "a[href=\"vendor-integration.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Vendor integration<a class=\"headerlink\" href=\"#vendor-integration\" title=\"Link to this heading\">#</a></h1><p>Chip vendors integrate by adding a backend directory under <code class=\"docutils literal notranslate\"><span class=\"pre\">dispatch/backends/vendor/</span></code>:</p>", "a[href=\"vendor-integration.html#registration-register-ops-py\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Registration (register_ops.py)<a class=\"headerlink\" href=\"#registration-register-ops-py\" title=\"Link to this heading\">#</a></h2>", "a[href=\"debugg-and-diagonostics.html#dispatch-log\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch log<a class=\"headerlink\" href=\"#dispatch-log\" title=\"Link to this heading\">#</a></h2><p>See which backend each fused op resolved to (written at server startup):</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
